 'apply-perk'(){const code=$('#perkInput').value.trim(),perk=(project.perkCodes||[]).find(p=>p.code===code);if(!perk)return toast('등록되지 않은 특전 코드예요.');if(save.perks.includes(perk.id))return toast('이미 적용한 특전이에요.');save.perks.push(perk.id);persist();render();toast('특전을 적용했어요.')},
 'event'(id){const event=(project.bonds||[]).filter(b=>save.bonds.includes(b.id)).flatMap(b=>b.events||[]).find(e=>e.id===id);if(!event)return;modal('<h2>'+esc(event.title)+'</h2><div class="prose">'+esc(event.body||'')+'</div><div class="actions"><button data-action="close">닫기</button><button class="primary" data-action="event-complete" data-id="'+esc(id)+'">이벤트 완료</button></div>')},
 'event-complete'(id){const event=(project.bonds||[]).filter(b=>save.bonds.includes(b.id)).flatMap(b=>b.events||[]).find(e=>e.id===id);if(!event)return;if(!save.events.includes(id))save.events.push(id);persist();close();render();toast('이벤트 완료를 기록했어요.')},
 edit(){mode='edit';render()},play(){mode='play';render()},'select-scene'(id){selected=id;selectedChoice=null;render()},'select-choice'(id){selectedChoice=id;render()},choose,
