 'add-choice'(){const c={id:uid(),label:'새로운 선택',description:'선택의 이야기를 적어 주세요.',target:project.scenes.find(s=>s.id!==selected)?.id||selected,effect:'glow',delta:0,min:0};sget().choices.push(c);selectedChoice=c.id;afterEdit()},
 'delete-choice'(){if(!confirm('이 선택지를 삭제할까요? 이 지점을 포함한 세이브는 직전까지 복원됩니다.'))return;sget().choices=sget().choices.filter(c=>c.id!==selectedChoice);selectedChoice=null;afterEdit()},
